(() => {
 if(display)return;
 const dialog=document.createElement('dialog');dialog.id='wirelessDialog';dialog.innerHTML=`<h2>무선 컨트롤러</h2><p>다른 기기에서 이 사이트의 컨트롤러를 열고 아래 코드를 입력하세요. 메인 점수판에서 승인하면 연결됩니다.</p><div id="wirelessCode" class="pair-code">------</div><p id="wirelessStatus">연결 코드를 만들면 12시간 동안 사용할 수 있습니다.</p><div id="wirelessPending"></div><div class="wireless-actions"><button id="wirelessCreate">연결 코드 만들기</button><button id="wirelessDisconnect">컨트롤러 해제</button><button id="wirelessCloseRoom">연결 종료</button><button id="wirelessDone">닫기</button></div><p><a href="./controller.html" target="_blank">이 기기에서 컨트롤러 화면 열기 ↗</a></p><p class="sub">두 기기 모두 인터넷이 필요합니다. 현재 비공개 사이트는 두 기기에서 같은 ChatGPT 계정으로 로그인하세요. 메인 점수판을 열어두고 화면 잠금을 해제하세요. 경기 데이터는 메인 기기에 저장됩니다.</p>`;document.body.append(dialog);
 const badge=document.createElement('div');badge.id='wirelessBadge';badge.hidden=true;document.body.append(badge);
 let direct=null,directFor=null,signal=null,directSince=0,lastDirect=0,lastPulse=0,directBuzzSeq=0;
 let room=null,inflight=false,ack=[],approve=null,reject=null,disconnect=false,close=false,lastOK=0,buzzDeadline=0,buzzing=false;
 try{room=JSON.parse(sessionStorage.getItem('courtboard-host-room'))}catch{}
 const setStatus=t=>{$('#wirelessStatus').textContent=t;badge.textContent=t;badge.hidden=!room};
 async function api(path,body,token){const r=await fetch((window.COURTBOARD_RELAY_URL?window.COURTBOARD_RELAY_URL.replace(/\/$/,'')+'/':'./')+'api/remote/'+path,{method:'POST',headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:JSON.stringify(body),signal:AbortSignal.timeout(4000),cache:'no-store'});let d;try{d=await r.json()}catch{throw Error('무선 서버에 연결할 수 없습니다. 서버가 있는 주소에서 실행하세요.')}if(!r.ok){const e=Error(d.error||'연결 오류');e.status=r.status;throw e}return d}
 function stateFor(g,live=false){return {id:g.id,a:g.a,b:g.b,mode:g.mode,period:g.period,periods:g.periods,minutes:g.minutes,otMinutes:g.otMinutes,score:[...g.score],fouls:[...g.fouls],timeouts:[...g.timeouts],limit:timeoutLimit(g),pos:g.pos,clock:live?remaining(g,'clock'):g.clock,shot:live?remaining(g,'shot'):g.shot,running:g.running,shotRunning:g.shotRunning,status:g.status,tournament:tour().name}}
 function snapshot(){const g=game();if(!g)return null;const result=stateFor(g,true),previous=g.history?.at(-1);result.undoPreview=previous?stateFor(previous):null;return result}
 function stopDirect(){direct?.close();direct=null;directFor=null;signal=null;lastDirect=0;stopBuzzer('remote');buzzing=false}
 function applyRemote(cmd){if(typeof cmd.id!=='string'||cmd.id.length>80||!(/^(toggle|shot|reset|14|pos|poss:[12]|period|periodPrev|undo|score:[01]:(-1|1|2|3)|foul:[01]:(-1|1)|timeout:[01]|toMinus:[01]|adjust:(clock:(-60000|60000|-1000|1000)|shot:(-1000|1000)))$/).test(cmd.action))return;ack.push(cmd.id);ack=ack.slice(-100);db.remoteReceipts??=[];if(db.remoteReceipts.includes(cmd.id)||cmd.game!==game()?.id)return;db.remoteReceipts.push(cmd.id);db.remoteReceipts=db.remoteReceipts.slice(-100);act(cmd.action,true);persist()}
 function sendDirect(){if(direct?.open)direct.send({kind:'state',state:snapshot(),ack:[...(db.remoteReceipts||[]),...ack].slice(-150)})}
 async function startDirect(id){if(!window.RTCPeerConnection)return;stopDirect();directFor=id;directSince=Date.now();directBuzzSeq=0;const link=new CourtDirectLink({onMessage:m=>{if(direct!==link||disconnect||close)return;lastDirect=Date.now();if(m.kind==='cmd'){applyRemote(m);sendDirect()}if(m.kind==='ping')direct.send({kind:'pong',at:m.at});if(m.kind==='buzz'&&Number.isSafeInteger(m.seq)&&m.seq>directBuzzSeq){directBuzzSeq=m.seq;buzzDeadline=m.active?Date.now()+1400:0;if(m.active&&!buzzing){buzzing=true;beep('remote',null)}if(!m.active){stopBuzzer('remote');buzzing=false}}},onClose:()=>{lastDirect=0;stopBuzzer('remote');buzzing=false}});direct=link;try{const offer=await link.offer();if(direct===link)signal={id:crypto.randomUUID(),for:id,offer}}catch{if(direct===link)stopDirect()}}
 function forget(){stopDirect();room=null;sessionStorage.removeItem('courtboard-host-room');$('#wirelessCode').textContent='------';$('#wirelessPending').replaceChildren();badge.hidden=true;stopBuzzer('remote');buzzing=false;buzzDeadline=0}
 async function pulse(){if(!room||inflight)return;if(direct?.open&&!approve&&!reject&&!disconnect&&!close&&Date.now()-lastPulse<1000)return;lastPulse=Date.now();inflight=true;const old=room,sentAck=[...ack],sentApprove=approve,sentReject=reject,sentDisconnect=disconnect,sentClose=close;
 try{const d=await api(old.code+'/host',{state:snapshot(),ack:sentAck,signal,approve:sentApprove,reject:sentReject,disconnect:sentDisconnect,close:sentClose},old.token);if(room!==old)return;lastOK=Date.now();ack=ack.filter(x=>!sentAck.includes(x));if(approve===sentApprove)approve=null;if(reject===sentReject)reject=null;if(sentDisconnect)disconnect=false;if(sentClose){close=false;forget();setStatus('무선 연결을 종료했습니다.');return}
 $('#wirelessCode').textContent=room.code;$('#wirelessCreate').textContent='새 연결 코드';
 const pending=$('#wirelessPending');pending.replaceChildren();if(d.pending){const p=document.createElement('p');p.textContent=d.pending.name+' 연결 요청';const yes=document.createElement('button');yes.textContent='연결 승인';yes.onclick=()=>{unlock();approve=d.pending.id;pulse()};const no=document.createElement('button');no.textContent='거절';no.onclick=()=>{reject=d.pending.id;pulse()};pending.append(p,yes,no);if(!dialog.open)dialog.showModal()}
 if(!d.controller){if(direct)stopDirect()}else if(directFor!==d.controller.id||(!direct?.open&&Date.now()-directSince>20000)){startDirect(d.controller.id)}else if(d.signal?.id===signal?.id&&d.signal?.answer){direct?.accept(d.signal.answer).catch(()=>{})}
 setStatus(direct?.open?'● 컨트롤러 직접 연결':d.controller?(d.now-d.controller.seen<3500?'● 컨트롤러 연결됨':'컨트롤러 연결 끊김 · 메인 조작 가능'):'연결 코드 '+room.code+' · 컨트롤러 대기');
 for(const cmd of d.commands){if(d.now-cmd.at<=2500)applyRemote(cmd);else ack.push(cmd.id)}
 if(d.buzzSeq>directBuzzSeq){directBuzzSeq=d.buzzSeq;buzzDeadline=Date.now()+Math.max(0,d.buzzUntil-d.now);if(buzzDeadline>Date.now()&&!buzzing){buzzing=true;beep('remote',null)}if(buzzDeadline<=Date.now()&&buzzing){stopBuzzer('remote');buzzing=false}}

 }catch(e){if(room!==old)return;setStatus(direct?.open?'● 직접 연결 · 서버 재접속 중':'무선 연결 끊김 · 메인 조작 가능');if([403,404,410].includes(e.status)){forget();setStatus(e.message)}}finally{inflight=false}}
 $('#wireless').onclick=()=>{unlock();dialog.showModal();if(room)$('#wirelessCode').textContent=room.code};$('#wirelessDone').onclick=()=>dialog.close();
 $('#wirelessCreate').onclick=async()=>{if(inflight)return;if(room&&!confirm('기존 연결을 종료하고 새 코드를 만들까요?'))return;$('#wirelessCreate').disabled=true;try{if(room)await api(room.code+'/host',{close:true},room.token);forget();const d=await api('create',{});room=d;sessionStorage.setItem('courtboard-host-room',JSON.stringify(room));$('#wirelessCode').textContent=d.code;setStatus('컨트롤러 연결 대기');pulse()}catch(e){setStatus(e.message)}finally{$('#wirelessCreate').disabled=false}};
 $('#wirelessDisconnect').onclick=()=>{if(room){disconnect=true;stopDirect();pulse()}};$('#wirelessCloseRoom').onclick=()=>{if(room){close=true;stopDirect();pulse()}};
 setInterval(sendDirect,100);setInterval(pulse,200);setInterval(()=>{if(buzzing&&(Date.now()>buzzDeadline||(Date.now()-lastOK>2000&&Date.now()-lastDirect>1400))){stopBuzzer('remote');buzzing=false}},100);if(room)pulse();
})();
